-- SPARK Mathematics original-v1 remaining original-source rubric parts:
-- Q3 transformation, Q7 patterns, Q8 quadratic, Q9 geometry,
-- Q10 matrices. These are DRAFT evidence allocations, not approvals.
-- Typed/visual answers and multi-step workings remain unresolved until
-- verified through a server-owned response artefact or internal rubric review.
BEGIN;
DO $v2_calibration$
DECLARE
 v_schemes jsonb := '{"p2-q3-v1::a":[{"code":"B1","kind":"B","marks":1,"description":"Correctly identifies a reflection, rather than a rotation or translation","field":"all","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Confirm the student explicitly names a reflection; accept an equivalent reflection description."}},{"code":"B2","kind":"B","marks":2,"description":"Correctly specifies mirror line y=0, the x-axis","field":"all","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Confirm x-axis, y=0, or an equivalent description of the horizontal axis through the origin; the full-line identification is worth two marks."}}],"p2-q7-v1::a":[{"code":"B1","kind":"B","marks":1,"description":"Gives 16 shaded tiles and 16 unshaded tiles for Design 4","field":"all","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Verify both shaded and unshaded values appear in their respective table columns or clearly labelled roles."}},{"code":"B2","kind":"B","marks":1,"description":"Obtains 32 total tiles for Design 4","field":"all","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Verify 32 occurs in the total column, not as an unrelated number."}}],"p2-q7-v1::b":[{"code":"B1","kind":"B","marks":1,"description":"States shaded count n²","field":"all","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Verify n² is assigned to shaded tiles, accepting equivalent multiplication n×n."}},{"code":"B2","kind":"B","marks":1,"description":"States unshaded count 4n","field":"all","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Verify 4n is assigned to unshaded border tiles, not to the shaded count."}},{"code":"B3","kind":"B","marks":1,"description":"Forms total by adding n² and 4n","field":"all","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Verify correct combination of distinct shaded and unshaded expressions."}},{"code":"B4","kind":"B","marks":1,"description":"Writes total expression n²+4n, or equivalent n(n+4)","field":"all","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Verify correct complete expression is explicitly assigned to total tiles. An algebraically equivalent but role-swapped response is not automatically correct."}}],"p2-q7-v1::c":[{"code":"M1","kind":"M","marks":1,"description":"Equates n²+4n to 165 and solves positive-design equation","field":"working","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Accept n²+4n=165, (n+15)(n-11)=0 or equivalent complete valid equation; reject negative design index -15."}},{"code":"A1","kind":"A","marks":1,"description":"Finds Design 11","field":"answer","depends":[],"profile":"source-calibration","check":{"type":"numeric","value":11,"tolerance":0.011}}],"p2-q7-v1::d":[{"code":"M1","kind":"M","marks":1,"description":"Uses n²=144, giving n=12","field":"working","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Check positive square root n=12 and clear use of 144 shaded tiles."}},{"code":"A1","kind":"A","marks":1,"description":"Finds 48 unshaded tiles","field":"answer","depends":[],"profile":"source-calibration","check":{"type":"numeric","value":48,"tolerance":0.011}}],"p2-q8-v1::a":[{"code":"M1","kind":"M","marks":1,"description":"Extracts factor 3 from quadratic terms","field":"working","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Check 3(x²-4x)+20 or equivalent rearrangement of 3x²-12x+20."}},{"code":"M2","kind":"M","marks":1,"description":"Completes square inside parentheses","field":"working","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Check x²-4x=(x-2)²-4 and correct expansion."}},{"code":"M3","kind":"M","marks":1,"description":"Simplifies constant -12+20=8","field":"working","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Check 3(x-2)²+8 after distributing 3 to the negative constant."}},{"code":"A1","kind":"A","marks":1,"description":"Produces completed-square form 3(x-2)²+8","field":"answer","depends":[],"profile":"source-calibration","check":{"type":"expression","value":"3(x-2)^2+8"}}],"p2-q8-v1::b1":[{"code":"M1","kind":"M","marks":1,"description":"Recognises 3(x-2)² cannot be negative","field":"working","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Verify correct minimum argument since coefficient is positive and square term ≥0."}},{"code":"A1","kind":"A","marks":1,"description":"States minimum value 8","field":"answer","depends":[],"profile":"source-calibration","check":{"type":"numeric","value":8,"tolerance":0.011}}],"p2-q8-v1::b2":[{"code":"M1","kind":"M","marks":1,"description":"Identifies square term zero when x-2=0","field":"working","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Accept equivalent reasoning from completed-square form or the vertex."}},{"code":"A1","kind":"A","marks":1,"description":"States minimum attained at x=2","field":"answer","depends":[],"profile":"source-calibration","check":{"type":"numeric","value":2,"tolerance":0.011}}],"p2-q8-v1::c":[{"code":"B1","kind":"B","marks":1,"description":"Identifies vertical axis through turning point","field":"all","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Verify line of symmetry is a vertical line through the vertex; do not credit a horizontal line."}},{"code":"A1","kind":"A","marks":1,"description":"Gives axis x=2","field":"answer","depends":[],"profile":"source-calibration","check":{"type":"sparkAnswer","answer":"x=2","accepted":["2","x = 2"]}}],"p2-q8-v1::d":[{"code":"M1","kind":"M","marks":1,"description":"Evaluates f(0)=20 for y-axis intercept","field":"working","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Check substitution x=0 into 3x²-12x+20, or equivalent direct constant-term insight."}},{"code":"A1","kind":"A","marks":1,"description":"States ordered intercept (0,20)","field":"answer","depends":[],"profile":"source-calibration","check":{"type":"coordinate","value":[0,20]}}],"p2-q9-v1::a1":[{"code":"M1","kind":"M","marks":1,"description":"Uses angle at centre twice inscribed angle on same arc","field":"working","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Verify circle theorem is properly identified with common arc AB."}},{"code":"M2","kind":"M","marks":1,"description":"Calculates central angle half: 104°/2","field":"working","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Check 104÷2, not 104×2, because the circumference angle is half central."}},{"code":"A1","kind":"A","marks":1,"description":"Finds angle ACB 52°","field":"answer","depends":[],"profile":"source-calibration","check":{"type":"numeric","value":52,"tolerance":0.011}}],"p2-q9-v1::a2":[{"code":"M1","kind":"M","marks":1,"description":"Uses OA=OB (radii), so equal base angles","field":"working","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Confirm triangle OAB is isosceles and applies angle sum 180°-104°."}},{"code":"A1","kind":"A","marks":1,"description":"Finds angle OAB 38°","field":"answer","depends":[],"profile":"source-calibration","check":{"type":"numeric","value":38,"tolerance":0.011}}],"p2-q9-v1::b2":[{"code":"M1","kind":"M","marks":1,"description":"Applies Pythagoras to 90 km and 120 km legs","field":"working","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Verify 90²+120²=PR² and the right angle at Q."}},{"code":"A1","kind":"A","marks":1,"description":"Finds distance PR=150 km","field":"answer","depends":[],"profile":"source-calibration","check":{"type":"numeric","value":150,"tolerance":0.11}}],"p2-q9-v1::b3":[{"code":"M1","kind":"M","marks":1,"description":"Calculates 53.1° at P from tan θ=120/90","field":"working","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Check tan θ=120/90, θ≈53.13°, then adds bearing 040°."}},{"code":"A1","kind":"A","marks":1,"description":"Obtains 093° bearing to nearest degree","field":"answer","depends":[],"profile":"source-calibration","check":{"type":"numeric","value":93,"tolerance":0.51}}],"p2-q10-v1::a":[{"code":"B1","kind":"B","marks":1,"description":"Calculates first matrix-product row (8,4)","field":"all","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Verify row 1·col1=8 and row1·col2=4, not just an unlabelled list."}},{"code":"B2","kind":"B","marks":1,"description":"Calculates second matrix-product row (4,9)","field":"all","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Verify row2·col1=4 and row2·col2=9 in the correct order."}},{"code":"A1","kind":"A","marks":1,"description":"Writes product matrix [[8,4],[4,9]]","field":"answer","depends":[],"profile":"source-calibration","check":{"type":"matrix","value":[[8,4],[4,9]]}}],"p2-q10-v1::c":[{"code":"M1","kind":"M","marks":1,"description":"Forms adjugate [[5,-3],[-1,2]]","field":"working","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Checks swapped diagonal 2↔5 and negated off-diagonal signs; reject incorrectly reordered entries."}},{"code":"M2","kind":"M","marks":1,"description":"Divides adjugate by determinant 7","field":"working","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Verify use of factor 1/7 on ALL matrix entries; determinant must be nonzero."}},{"code":"B1","kind":"B","marks":1,"description":"States correct inverse (1/7)[[5,-3],[-1,2]]","field":"all","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Verify equivalent scaled matrix, e.g. [[5/7,-3/7],[-1/7,2/7]], and M·M⁻¹=I if submitted."}}],"p2-q10-v1::d":[{"code":"M1","kind":"M","marks":1,"description":"Expresses system as M(x,y)^T=(13,17)^T","field":"working","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Check the correct equation layout and order of x/y in M."}},{"code":"M2","kind":"M","marks":1,"description":"Multiplies M⁻¹ by (13,17)^T to give (14,21)^T /7","field":"working","depends":[],"profile":"source-calibration","check":{"type":"manual-verification","evidence":"Check 5(13)-3(17)=14 and -13+2(17)=21, or equivalent matrix elimination."}},{"code":"A1","kind":"A","marks":2,"description":"Solves x=2 and y=3 in that order","field":"answer","depends":[],"profile":"source-calibration","check":{"type":"ordered","value":[2,3],"tolerance":0.000001}}]}'::jsonb;
 v_answers jsonb := '{"p2-q3-v1::a":"A reflection in the x-axis (y = 0)","p2-q7-v1::a":"16, 16, 32","p2-q7-v1::b":"shaded n^2; unshaded 4n; total n^2 + 4n","p2-q7-v1::c":"11","p2-q7-v1::d":"48","p2-q8-v1::a":"3(x - 2)^2 + 8","p2-q8-v1::b1":"8","p2-q8-v1::b2":"2","p2-q8-v1::c":"x = 2","p2-q8-v1::d":"(0, 20)","p2-q9-v1::a1":"52 degrees, because the angle at the centre is twice the angle at the circumference when both stand on the same arc AB","p2-q9-v1::a2":"38","p2-q9-v1::b2":"150","p2-q9-v1::b3":"093","p2-q10-v1::a":"[[8, 4], [4, 9]]","p2-q10-v1::c":"(1/7)[[5, -3], [-1, 2]]","p2-q10-v1::d":"x = 2, y = 3"}'::jsonb;
 v_paper spark_grading_private.rubrics_v2%rowtype;
 v_updated jsonb;
 v_found int;
 v_bad int;
BEGIN
 SELECT * INTO v_paper FROM spark_grading_private.rubrics_v2
 WHERE subject_id='mathematics' AND paper_id='original-v1'
   AND rubric_version='source-scheme-draft-v2' FOR UPDATE;
 IF NOT FOUND OR v_paper.active OR v_paper.verification_status<>'draft'
  OR v_paper.verified_by IS NOT NULL OR v_paper.verified_at IS NOT NULL
  OR v_paper.source_sha256 IS DISTINCT FROM
   encode(pg_catalog.sha256(convert_to(v_paper.criteria::text,'UTF8')),'hex')
 THEN RAISE EXCEPTION 'Mathematics original-v1 source or approval changed'; END IF;
 IF jsonb_array_length(v_paper.criteria)<>45 THEN
  RAISE EXCEPTION 'Mathematics original-v1 45-part source changed';
 END IF;
 SELECT count(*),count(*) FILTER(WHERE
   c->>'id' IS DISTINCT FROM c->>'sourcePartId'
   OR c->'sourceMarking'->>'answer' IS DISTINCT FROM v_answers->>(c->>'id')
   OR jsonb_typeof(c->'sourceMarking'->'criteria') IS DISTINCT FROM 'null'
   OR (c->>'maxMarks')::int IS DISTINCT FROM
    (SELECT sum((k->>'marks')::int) FROM jsonb_array_elements(v_schemes->(c->>'id')) k)
 ) INTO v_found,v_bad FROM jsonb_array_elements(v_paper.criteria)c
 WHERE v_schemes ? (c->>'id');
 IF v_found<>17 OR v_bad<>0 THEN
  RAISE EXCEPTION 'Math original-v1 Q3/Q7-Q10 source mismatch: % of 17, % invalid',v_found,v_bad;
 END IF;
 SELECT jsonb_agg(
  CASE WHEN v_schemes ? (x.part->>'id')
    THEN jsonb_set(x.part,'{sourceMarking,criteria}',v_schemes->(x.part->>'id'))
    ELSE x.part END
  ORDER BY x.ordinal
 ) INTO v_updated FROM jsonb_array_elements(v_paper.criteria) WITH ORDINALITY x(part,ordinal);
 IF jsonb_array_length(v_updated)<>45 OR
  (SELECT count(*) FROM jsonb_array_elements(v_updated) c
   WHERE jsonb_typeof(c->'sourceMarking'->'criteria')='array')<>45 THEN
  RAISE EXCEPTION 'Math original-v1 is incomplete after draft calibration';
 END IF;
 UPDATE spark_grading_private.rubrics_v2 SET
  criteria=v_updated,
  source_sha256=encode(pg_catalog.sha256(convert_to(v_updated::text,'UTF8')),'hex')
 WHERE subject_id='mathematics' AND paper_id='original-v1'
  AND rubric_version='source-scheme-draft-v2'
  AND active=false AND verification_status='draft';
 IF NOT FOUND THEN RAISE EXCEPTION 'Math draft-only source calibration rejected'; END IF;
END $v2_calibration$;
COMMIT;
